const entreprise = $('Lire Entreprises a generer').first().json;
const offres = $('Lire offres entreprise').all().map(i => i.json);

const offresText = offres.map((o, i) =>
  `Offre ${i+1}: ${o.nom_offre}\n  Description: ${o.description}\n  Cible ideale: ${o.cible_ideale}\n  Mots-cles: ${o.mots_cles}\n  Problemes resolus: ${o.problemes_resolus}`
).join('\n\n');

return [{
  json: {
    entreprise_nom: entreprise.nom,
    entreprise_description: entreprise.description,
    entreprise_proposition_valeur: entreprise.proposition_valeur,
    entreprise_secteur: entreprise.secteur,
    offresText
  }
}];

const geminiResponse = $json.candidates[0].content.parts[0].text;
const parsed = JSON.parse(geminiResponse);
const entrepriseNom = $('Preparer contexte personas').first().json.entreprise_nom;

return {
  json: {
    entreprise_id: entrepriseNom,
    personas: parsed.personas
  }
};

var emails = [];
for (const item of $input.all()) {
  if (item.json.person && item.json.person.email != null) {
    emails.push(item.json.person.email);
  }
}
return [{ json: { emails } }];

const originalItems = $('Recuperer email (Apollo)').all();
const validatedList = $input.first().json.emails || [];

const validationMap = {};
for (const v of validatedList) {
  validationMap[v.email?.toLowerCase()] = v;
}

return originalItems.map(item => {
  const person = item.json.person || {};
  const email = person.email || '';
  const validation = validationMap[email.toLowerCase()] || {};
  const linkedinUrl = person.linkedin_url || '';
  let linkedinUsername = '';
  if (linkedinUrl) {
    const match = linkedinUrl.match(/linkedin\.com\/in\/([^/]+)/);
    if (match) linkedinUsername = match[1];
  }

  return {
    json: {
      apollo_id: person.id,
      nom: person.name || ((person.first_name || '') + ' ' + (person.last_name || '')).trim(),
      linkedin_url: linkedinUrl,
      linkedin_username: linkedinUsername,
      email: email,
      email_status: validation.result || '',
      contacts_scrape_status: email ? (validation.result === 'deliverable' ? 'finished' : (validation.result === 'risky' ? 'finished' : 'invalid_email')) : 'invalid_email',
      extract_username_status: linkedinUsername ? 'finished' : 'pending'
    }
  };
});

const items = $input.all();
const prepData = $('Preparer URLs LinkedIn').all();
const groups = {};

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  // Utiliser pairedItem pour matcher avec les donnees originales
  const pairedIndex = items[i].pairedItem?.item ?? i;
  const prep = prepData[pairedIndex]?.json || {};
  const key = prep.apollo_id || `item_${i}`;

  if (!groups[key]) {
    groups[key] = {
      apollo_id: prep.apollo_id,
      row_number: prep.row_number,
      linkedinUrl: prep.linkedinUrl,
      postTexts: []
    };
  }

  // Gerer les differents noms de champs possibles d'Apify
  const text = j.postText || j.text || j.content || j.postContent || '';
  if (text) groups[key].postTexts.push(text);
}

return Object.values(groups).map(obj => ({
  json: {
    ...obj,
    allPosts: obj.postTexts.join('\n\n')
  }
}));

const inputItems = $input.all();
const prepData = $('Preparer URLs LinkedIn').all();
const items = [];

if (!inputItems || inputItems.length === 0) {
  return [{ json: { message: 'No profiles found' } }];
}

inputItems.forEach((profile, index) => {
  const data = profile.json;
  // Utiliser pairedItem pour matcher avec les donnees originales
  const pairedIndex = profile.pairedItem?.item ?? index;
  const prep = prepData[pairedIndex]?.json || {};
  const apolloId = prep.apollo_id || `profile_${index}`;
  const rowNumber = prep.row_number || null;
  const linkedinUrl = prep.linkedinUrl || '';

  if (!data || data.message) {
    items.push({ json: { apollo_id: apolloId, row_number: rowNumber, linkedin_url: linkedinUrl, message: 'No profile found' } });
    return;
  }

  const exclude = ['apollo_id', 'row_number', 'linkedin_url'];
  const profileData = {
    apollo_id: apolloId,
    row_number: rowNumber,
    linkedin_url: linkedinUrl,
    fullName: data.fullName || `${data.firstName || ''} ${data.lastName || ''}`.trim(),
    headline: data.headline || 'No headline',
    currentPosition: data.jobTitle || 'Not specified',
    currentCompany: data.companyName || 'Not specified',
    location: data.addressWithoutCountry || 'Not specified',
    about: (data.about || 'No about section').substring(0, 500),
    connections: data.connections || 0,
    followers: data.followers || 0
  };

  const parts = [];
  for (const [key, value] of Object.entries(profileData)) {
    if (!exclude.includes(key) && value && value !== '') {
      parts.push(`${key}: ${value}`);
    }
  }
  profileData.profileSummary = parts.join('\n');
  items.push({ json: profileData });
});

return items;

